!function(){"use strict";function aprobacionDocumentoCtrl($scope,$injector){let OPTION_APROBACION={0:{codigoDocOrigen:"NE",codigoDocDestino:"FV"},1:{codigoDocOrigen:"PR",codigoDocDestino:"FV"},2:{codigoDocOrigen:"PR",codigoDocDestino:"NE"}};$scope.askToOpenModalOption=async function(){try{const swalWithBootstrapButtons=Swal.mixin({customClass:{confirmButton:"btn btn-success",cancelButton:"btn btn-danger m-l-5"},buttonsStyling:!1});swalWithBootstrapButtons.fire({title:"Opción Aprobación Documento",input:"select",inputOptions:{0:"NOTA DE ENTREGA A FACTURA",1:"PROFORMA A FACTURA",2:"PROFORMA A NOTA DE ENTREGA"},inputPlaceholder:"Seleccionar...",showCancelButton:!0,confirmButtonText:'Continuar <i class="fa fa-arrow-right"></i>',cancelButtonText:"<small>&times; Cerrar</small>",reverseButtons:!1,allowOutsideClick:!1,focusConfirm:!0,inputValidator:value=>!value&&"Seleccione la opción de aprobación"}).then(result=>{if(result.isConfirmed){let resultOption=OPTION_APROBACION[result.value];console.log(resultOption)}})}catch(error){console.log(error)}}}app.controller("aprobacionDocumentoCtrl",aprobacionDocumentoCtrl),aprobacionDocumentoCtrl.$inject=["$scope","$injector"]}(window.angular);